var textForPages =["\u041d\u043e\u0432\u043e\u0441\u0442\u043d\u043e\u0439 \u0434\u0430\u0439\u0434\u0436\u0435\u0441\u0442 12\u201316 \u044f\u043d\u0432\u0430\u0440\u044f 2026 \u0433\u043e\u0434\u0430\u000d\u000a01 09\u000d\u000a\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u000d\u000a\u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439\u000d\u000a\u0413\u043b\u0430\u0432\u043d\u043e\u0435 \u0432 \u0432\u044b\u043f\u0443\u0441\u043a\u0435\u000d\u000aMaaden \u0432\u043b\u043e\u0436\u0438\u0442 $110 \u043c\u043b\u0440\u0434 \u0432 \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u0435 \u000d\u000a\u0433\u043e\u0440\u043d\u043e\u0434\u043e\u0431\u044b\u0432\u0430\u044e\u0449\u0435\u0433\u043e \u0441\u0435\u043a\u0442\u043e\u0440\u0430 \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0439 \u000d\u000a\u0410\u0440\u0430\u0432\u0438\u0438\u000d\u000a\u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u0443\u0442\u0440\u043e\u0438\u0442 \u0434\u043e\u0431\u044b\u0447\u0443 \u0437\u043e\u043b\u043e\u0442\u0430 \u0438 \u0444\u043e\u0441\u0444\u0430\u0442\u043e\u0432, \u0443\u0434\u0432\u043e\u0438\u0442 \u000d\u000a\u0430\u043b\u044e\u043c\u0438\u043d\u0438\u0435\u0432\u044b\u0439 \u0441\u0435\u0433\u043c\u0435\u043d\u0442 \u0438 \u0440\u0435\u0437\u043a\u043e \u0440\u0430\u0441\u0448\u0438\u0440\u0438\u0442 \u000d\u000a\u0433\u0435\u043e\u043b\u043e\u0433\u043e\u0440\u0430\u0437\u0432\u0435\u0434\u043a\u0443 \u0432 \u0440\u0430\u043c\u043a\u0430\u0445 \u0434\u0435\u0441\u044f\u0442\u0438\u043b\u0435\u0442\u043d\u0435\u0439 \u000d\u000a\u0438\u043d\u0432\u0435\u0441\u0442\u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u044b.\u000d\u000aMaersk \u0432\u043e\u0437\u043e\u0431\u043d\u043e\u0432\u043b\u044f\u0435\u0442 \u043f\u0440\u043e\u0445\u043e\u0434 \u0447\u0435\u0440\u0435\u0437 \u2028\u000d\u000a\u041a\u0440\u0430\u0441\u043d\u043e\u0435 \u043c\u043e\u0440\u0435\u000d\u000a\u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u043d\u0430\u0447\u0430\u043b\u0430 \u043e\u0441\u0442\u043e\u0440\u043e\u0436\u043d\u043e\u0435 \u0432\u043e\u0437\u0432\u0440\u0430\u0449\u0435\u043d\u0438\u0435 \u0441\u0443\u0434\u043e\u0432 \u000d\u000a\u043d\u0430 \u043c\u0430\u0440\u0448\u0440\u0443\u0442 \u0447\u0435\u0440\u0435\u0437 \u0421\u0443\u044d\u0446\u043a\u0438\u0439 \u043a\u0430\u043d\u0430\u043b \u043f\u043e\u0441\u043b\u0435 \u043f\u0435\u0440\u0435\u043c\u0438\u0440\u0438\u044f \u000d\u000a\u0432 \u0413\u0430\u0437\u0435, \u043d\u0435\u0441\u043c\u043e\u0442\u0440\u044f \u043d\u0430 \u0442\u043e, \u0447\u0442\u043e \u0442\u0440\u0430\u0444\u0438\u043a \u0432\u0441\u0435 \u0435\u0449\u0435 \u043d\u0430 60% \u000d\u000a\u043d\u0438\u0436\u0435 \u043d\u043e\u0440\u043c\u044b.\u000d\u000aTotalEnergies \u0438 Bapco \u0441\u043e\u0437\u0434\u0430\u044e\u0442 \u0442\u043e\u0440\u0433\u043e\u0432\u043e\u0435 \u0421\u041f\u000d\u000a\u0421\u043e\u0432\u043c\u0435\u0441\u0442\u043d\u043e\u0435 \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u0435 \u0431\u0443\u0434\u0435\u0442 \u0437\u0430\u043d\u0438\u043c\u0430\u0442\u044c\u0441\u044f \u000d\u000a\u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0435\u0439 \u043f\u0440\u043e\u0434\u0443\u043a\u0446\u0438\u0438 \u041d\u041f\u0417 Sitra \u0438 \u0443\u043a\u0440\u0435\u043f\u0438\u0442 \u043f\u043e\u0437\u0438\u0446\u0438\u0438 \u000d\u000aTotalEnergies \u0432 \u0431\u0430\u0445\u0440\u0435\u0439\u043d\u0441\u043a\u043e\u043c \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u0435 \u0442\u043e\u043f\u043b\u0438\u0432\u0430.\u000d\u000aStarlink \u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u043e \u0432\u044b\u0445\u043e\u0434\u0438\u0442 \u043d\u0430 \u0440\u044b\u043d\u043e\u043a \u000d\u000a\u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0430\u000d\u000a\u0421\u043f\u0443\u0442\u043d\u0438\u043a\u043e\u0432\u044b\u0439 \u0438\u043d\u0442\u0435\u0440\u043d\u0435\u0442 \u0431\u0443\u0434\u0435\u0442 \u0434\u043e\u0441\u0442\u0443\u043f\u0435\u043d \u043f\u043e \u0432\u0441\u0435\u0439 \u000d\u000a\u0442\u0435\u0440\u0440\u0438\u0442\u043e\u0440\u0438\u0438 \u0441\u0442\u0440\u0430\u043d\u044b \u0438 \u0432 \u0442\u0435\u0440\u0440\u0438\u0442\u043e\u0440\u0438\u0430\u043b\u044c\u043d\u044b\u0445 \u0432\u043e\u0434\u0430\u0445.\u000d\u000aMaaden \u0443\u0432\u0435\u043b\u0438\u0447\u0438\u043b\u0430 \u043e\u0446\u0435\u043d\u043a\u0443 \u0437\u0430\u043f\u0430\u0441\u043e\u0432 \u0437\u043e\u043b\u043e\u0442\u0430 \u000d\u000a\u043d\u0430 8 \u043c\u043b\u043d \u0443\u043d\u0446\u0438\u0439\u000d\u000a\u0420\u043e\u0441\u0442 \u0437\u0430\u043f\u0430\u0441\u043e\u0432 \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u0430\u043b \u0430\u043a\u0446\u0438\u0438 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u000d\u000a\u0438 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u043b \u0440\u0435\u0441\u0443\u0440\u0441\u043d\u044b\u0439 \u043f\u043e\u0442\u0435\u043d\u0446\u0438\u0430\u043b \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0439 \u000d\u000a\u0410\u0440\u0430\u0432\u0438\u0438.\u000d\u000a\u0421\u043e\u043c\u0430\u043b\u0438 \u0440\u0430\u0437\u0440\u044b\u0432\u0430\u0435\u0442 \u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u044f \u0441 \u041e\u0410\u042d \u000d\u000a\u043f\u043e \u043f\u043e\u0440\u0442\u0430\u043c\u000d\u000a\u0410\u043d\u043d\u0443\u043b\u0438\u0440\u043e\u0432\u0430\u043d\u044b \u0432\u0441\u0435 \u043a\u043e\u043c\u043c\u0435\u0440\u0447\u0435\u0441\u043a\u0438\u0435 \u0438 \u043e\u0431\u043e\u0440\u043e\u043d\u043d\u044b\u0435 \u000d\u000a\u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u044f, \u0432\u043a\u043b\u044e\u0447\u0430\u044f \u043f\u0440\u043e\u0435\u043a\u0442\u044b DP World \u0432 \u0411\u0435\u0440\u0431\u0435\u0440\u0435, \u000d\u000a\u0411\u043e\u0441\u0430\u0441\u043e \u0438 \u041a\u0438\u0441\u043c\u0430\u0439\u043e.\u000d\u000aBapco \u0432\u043e\u0437\u043e\u0431\u043d\u043e\u0432\u043b\u044f\u0435\u0442 \u044d\u043a\u0441\u043f\u043e\u0440\u0442 \u0434\u0438\u0437\u0435\u043b\u044f \u000d\u000a\u0432 \u0410\u0432\u0441\u0442\u0440\u0430\u043b\u0438\u044e\u000d\u000a\u041f\u0435\u0440\u0432\u044b\u0435 \u0437\u0430 2,5 \u0433\u043e\u0434\u0430 \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0438 \u0441\u0438\u0433\u043d\u0430\u043b\u0438\u0437\u0438\u0440\u0443\u044e\u0442 \u000d\u000a\u043e \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u0438 \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u043d\u043e\u0433\u043e \u043f\u043e\u0442\u0435\u043d\u0446\u0438\u0430\u043b\u0430 \u000d\u000a\u0431\u0430\u0445\u0440\u0435\u0439\u043d\u0441\u043a\u043e\u0433\u043e \u041d\u041f\u0417.\u000d\u000a\u041e\u043c\u0430\u043d \u043f\u0440\u0438\u0432\u043b\u0435\u043a $400 \u043c\u043b\u043d \u043d\u0430 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0439 \u000d\u000a\u043c\u0435\u0434\u043d\u044b\u0439 \u043f\u0440\u043e\u0435\u043a\u0442 Mazoon\u000d\u000a\u041f\u0440\u043e\u0435\u043a\u0442 \u0441\u0442\u0430\u043d\u0435\u0442 \u043a\u043b\u044e\u0447\u0435\u0432\u044b\u043c \u044d\u043b\u0435\u043c\u0435\u043d\u0442\u043e\u043c \u000d\u000a\u0433\u043e\u0440\u043d\u043e\u0434\u043e\u0431\u044b\u0432\u0430\u044e\u0449\u0435\u0439 \u0441\u0442\u0440\u0430\u0442\u0435\u0433\u0438\u0438 \u0441\u0442\u0440\u0430\u043d\u044b.\u000d\u000aGecamines \u043a\u0443\u043f\u0438\u0442 100 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d \u043c\u0435\u0434\u0438 \u000d\u000a\u0443 \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u043e\u0439 CMOC \u0434\u043b\u044f \u0440\u044b\u043d\u043a\u0430 \u0421\u0428\u0410\u000d\u000a\u0421\u0434\u0435\u043b\u043a\u0430 \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0430 \u043d\u0430 \u043f\u0435\u0440\u0435\u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u043f\u043e\u0442\u043e\u043a\u043e\u0432 \u000d\u000a\u043c\u0435\u0434\u0438 \u0432 \u043f\u043e\u043b\u044c\u0437\u0443 \u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u043e\u0433\u043e \u0440\u044b\u043d\u043a\u0430.\u000d\u000aS&P Global: \u041a\u0438\u0442\u0430\u0439 \u0438 \u0410\u0437\u0438\u044f \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0430\u0442 \u2028\u000d\u000a60% \u0440\u043e\u0441\u0442\u0430 \u0441\u043f\u0440\u043e\u0441\u0430 \u043d\u0430 \u043c\u0435\u0434\u044c \u0434\u043e 2040 \u0433\u043e\u0434\u0430\u000d\u000a\u042d\u043d\u0435\u0440\u0433\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u043f\u0435\u0440\u0435\u0445\u043e\u0434, \u0418\u0418 \u0438 \u0434\u0430\u0442\u0430 \u0446\u0435\u043d\u0442\u0440\u044b \u000d\u000a\u0441\u0442\u0430\u043d\u043e\u0432\u044f\u0442\u0441\u044f \u0433\u043b\u0430\u0432\u043d\u044b\u043c\u0438 \u0434\u0440\u0430\u0439\u0432\u0435\u0440\u0430\u043c\u0438 \u0440\u044b\u043d\u043a\u0430.\u000d\u000a\u0421\u0428\u0410 \u043e\u0431\u044a\u044f\u0432\u0438\u043b\u0438 \u043a\u0443\u0440\u0441 \u043d\u0430 \u043f\u043e\u0434\u0440\u044b\u0432 \u000d\u000a\u0434\u043e\u043c\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f \u041a\u0438\u0442\u0430\u044f \u0432 \u0440\u0435\u0434\u043a\u043e\u0437\u0435\u043c\u0435\u043b\u044c\u043d\u044b\u0445 \u000d\u000a\u043c\u0435\u0442\u0430\u043b\u043b\u0430\u0445\u000d\u000a\u0410\u0434\u043c\u0438\u043d\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u044f \u0422\u0440\u0430\u043c\u043f\u0430 \u0440\u0430\u0441\u0441\u043c\u0430\u0442\u0440\u0438\u0432\u0430\u0435\u0442 \u0440\u0435\u0434\u043a\u043e\u0437\u0435\u043c\u044b \u043a\u0430\u043a \u000d\u000a\u043a\u043b\u044e\u0447\u0435\u0432\u043e\u0439 \u044d\u043b\u0435\u043c\u0435\u043d\u0442 \u0442\u043e\u0440\u0433\u043e\u0432\u044b\u0445 \u0432\u043e\u0439\u043d.","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a \u0438 \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 12\u201316 \u044f\u043d\u0432\u0430\u0440\u044f 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b #\u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0438\u000d\u000aMaaden \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0440\u0443\u0435\u0442 $110 \u043c\u043b\u0440\u0434 \u0432 \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u0435 \u000d\u000a\u0441\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0433\u043e \u0433\u043e\u0440\u043d\u043e\u0434\u043e\u0431\u044b\u0432\u0430\u044e\u0449\u0435\u0433\u043e \u0441\u0435\u043a\u0442\u043e\u0440\u0430\u000d\u000a\u041e\u0431\u0449\u0430\u044f \u0441\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u044c \u043c\u0438\u043d\u0435\u0440\u0430\u043b\u044c\u043d\u044b\u0445 \u0440\u0435\u0441\u0443\u0440\u0441\u043e\u0432 \u0441\u0442\u0440\u0430\u043d\u044b, \u0432\u043a\u043b\u044e\u0447\u0430\u044f \u0444\u043e\u0441\u0444\u0430\u0442\u044b, \u0431\u043e\u043a\u0441\u0438\u0442\u044b, \u0437\u043e\u043b\u043e\u0442\u043e, \u043c\u0435\u0434\u044c \u2028\u000d\u000a\u0438 \u0440\u0435\u0434\u043a\u043e\u0437\u0435\u043c\u0435\u043b\u044c\u043d\u044b\u0435 \u043c\u0435\u0442\u0430\u043b\u043b\u044b, \u0434\u043e\u0441\u0442\u0438\u0433\u0430\u0435\u0442 \u043f\u043e\u0447\u0442\u0438 $2,5 \u0442\u0440\u043b\u043d.\u000d\u000a\u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0430\u044f \u0433\u043e\u0440\u043d\u043e\u0434\u043e\u0431\u044b\u0432\u0430\u044e\u0449\u0430\u044f \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u000d\u000aMaaden \u043f\u043b\u0430\u043d\u0438\u0440\u0443\u0435\u0442 \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0440\u043e\u0432\u0430\u0442\u044c $110 \u043c\u043b\u0440\u0434 \u2028\u000d\u000a\u0432 \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u0435 \u043e\u0442\u0440\u0430\u0441\u043b\u0438 \u0432 \u0442\u0435\u0447\u0435\u043d\u0438\u0435 \u0434\u0435\u0441\u044f\u0442\u0438 \u043b\u0435\u0442. \u000d\u000a\u041e\u0431 \u044d\u0442\u043e\u043c \u0433\u0435\u043d\u0434\u0438\u0440\u0435\u043a\u0442\u043e\u0440 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u000d\u000a\u0411\u043e\u0431 \u0423\u0438\u043b\u0442.\u000a\u000d\u000a\u0412 \u0431\u043b\u0438\u0436\u0430\u0439\u0448\u0438\u0435 \u043f\u044f\u0442\u044c \u043b\u0435\u0442 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u0440\u0435\u0430\u043b\u0438\u0437\u0443\u0435\u0442 \u000d\u000a\u043c\u0430\u0441\u0448\u0442\u0430\u0431\u043d\u0443\u044e \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u0443, \u043a\u043e\u0442\u043e\u0440\u0430\u044f \u000d\u000a\u043f\u0440\u0435\u0434\u0443\u0441\u043c\u0430\u0442\u0440\u0438\u0432\u0430\u0435\u0442 \u0443\u0432\u0435\u043b\u0438\u0447\u0435\u043d\u0438\u0435 \u0434\u043e\u0431\u044b\u0447\u0438 \u0437\u043e\u043b\u043e\u0442\u0430 \u000d\u000a\u0437\u0430\u044f\u0432\u0438\u043b\u000d\u000a\u0438 \u0444\u043e\u0441\u0444\u0430\u0442\u043e\u0432 \u0432 \u0442\u0440\u0438 \u0440\u0430\u0437\u0430, \u0430 \u0442\u0430\u043a\u0436\u0435 \u0434\u0432\u0443\u043a\u0440\u0430\u0442\u043d\u043e\u0435 \u000d\u000a\u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043d\u0438\u0435 \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u0435\u0432\u043e\u0433\u043e \u0441\u0435\u0433\u043c\u0435\u043d\u0442\u0430.\u000a\u000d\u000a\u041a\u0440\u043e\u043c\u0435 \u0442\u043e\u0433\u043e, Maaden \u043f\u043b\u0430\u043d\u0438\u0440\u0443\u0435\u0442 \u0443\u0442\u0440\u043e\u0438\u0442\u044c \u043e\u0431\u044a\u0435\u043c\u044b \u000d\u000a\u0433\u0435\u043e\u043b\u043e\u0433\u043e\u0440\u0430\u0437\u0432\u0435\u0434\u043e\u0447\u043d\u044b\u0445 \u0440\u0430\u0431\u043e\u0442 \u043f\u043e \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044e \u000d\u000a\u0441 \u043f\u0440\u043e\u0448\u043b\u044b\u043c \u0433\u043e\u0434\u043e\u043c. \u0423\u0436\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044e\u0449\u0430\u044f \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u0430 \u000d\u000a\u0440\u0430\u0437\u0432\u0435\u0434\u043a\u0438 \u0432 \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0438\u0435 \u0433\u043e\u0434\u044b \u0432\u0445\u043e\u0434\u0438\u0442 \u0432 \u0447\u0438\u0441\u043b\u043e \u000d\u000a\u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0445 \u0432 \u043c\u0438\u0440\u0435.\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0430\u044f Maaden \u043f\u043e\u0434\u043d\u044f\u043b\u0430 \u043e\u0446\u0435\u043d\u043a\u0443 \u0437\u043e\u043b\u043e\u0442\u044b\u0445 \u000d\u000a\u0437\u0430\u043f\u0430\u0441\u043e\u0432 \u043f\u043e\u0447\u0442\u0438 \u043d\u0430 8 \u043c\u043b\u043d \u0443\u043d\u0446\u0438\u0439\u000d\u000a\u041f\u043e\u0441\u043b\u0435 \u0443\u0432\u0435\u043b\u0438\u0447\u0435\u043d\u0438\u044f \u043e\u0431\u044a\u0435\u043c\u0430 \u0434\u043e\u043a\u0430\u0437\u0430\u043d\u043d\u044b\u0445 \u0437\u0430\u043f\u0430\u0441\u043e\u0432 \u0437\u043e\u043b\u043e\u0442\u0430 \u0430\u043a\u0446\u0438\u0438 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u0432\u044b\u0440\u043e\u0441\u043b\u0438 \u043d\u0430 5%. \u000d\u000a\u0421 \u043d\u0430\u0447\u0430\u043b\u0430 \u0433\u043e\u0434\u0430 \u0431\u0443\u043c\u0430\u0433\u0438 Maaden \u043d\u0430 \u0441\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0439 \u0431\u0438\u0440\u0436\u0435 Tadawul \u043f\u0440\u0438\u0431\u0430\u0432\u0438\u043b\u0438 11%.\u000d\u000a\u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0438\u0439 \u0433\u043e\u0440\u043d\u043e\u0434\u043e\u0431\u044b\u0442\u0447\u0438\u043a Maaden \u000d\u000a\u043e\u0446\u0435\u043d\u043a\u0443 \u0437\u0430\u043f\u0430\u0441\u043e\u0432 \u0437\u043e\u043b\u043e\u0442\u0430 \u043f\u043e\u0447\u0442\u0438 \u043d\u0430 8 \u043c\u043b\u043d \u0443\u043d\u0446\u0438\u0439 \u000d\u000a\u043f\u043e\u0441\u043b\u0435 \u043d\u043e\u0432\u044b\u0445 \u0433\u0435\u043e\u043b\u043e\u0433\u043e\u0440\u0430\u0437\u0432\u0435\u0434\u043e\u0447\u043d\u044b\u0445 \u0440\u0430\u0431\u043e\u0442 \u000d\u000a\u043d\u0430 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044e\u0449\u0438\u0445 \u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u044f\u0445. \u000a\u000d\u000a\u041a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0435\u0435 \u0432 \u0441\u0442\u0440\u0430\u043d\u0435 \u0437\u043e\u043b\u043e\u0442\u043e\u0434\u043e\u0431\u044b\u0432\u0430\u044e\u0449\u0435\u0435 \u000d\u000a\u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u0435 Mansourah Massarah \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0438\u043b\u043e \u000d\u000a\u043f\u0440\u0438\u0440\u043e\u0441\u0442 \u0432 3 \u043c\u043b\u043d \u0443\u043d\u0446\u0438\u0439. \u041e\u0446\u0435\u043d\u043a\u0430 \u0437\u0430\u043f\u0430\u0441\u043e\u0432 \u000d\u000a\u043d\u0430 \u0443\u0447\u0430\u0441\u0442\u043a\u0435 Wadi Al Jaww \u0442\u0430\u043a\u0436\u0435 \u0441\u043e\u0441\u0442\u0430\u0432\u0438\u043b\u0430 \u000d\u000a\u0443\u0432\u0435\u043b\u0438\u0447\u0438\u043b 3 \u043c\u043b\u043d \u0443\u043d\u0446\u0438\u0439. \u0415\u0449\u0435 1,7 \u043c\u043b\u043d \u0443\u043d\u0446\u0438\u0439 \u0434\u043e\u0431\u0430\u0432\u0438\u043b\u0438 \u000d\u000a\u0443\u0447\u0430\u0441\u0442\u043a\u0438 Uruq 20/21 \u0438 Umm As Salam.\u000a\u000d\u000a\u0413\u0435\u043e\u043b\u043e\u0433\u043e\u0440\u0430\u0437\u0432\u0435\u0434\u043e\u0447\u043d\u044b\u0435 \u0440\u0430\u0431\u043e\u0442\u044b \u0432 \u0446\u0435\u043d\u0442\u0440\u0430\u043b\u044c\u043d\u043e\u0439 \u000d\u000a\u0447\u0430\u0441\u0442\u0438 \u0410\u0440\u0430\u0432\u0438\u0439\u0441\u043a\u043e\u0433\u043e \u043f\u043e\u043b\u0443\u043e\u0441\u0442\u0440\u043e\u0432\u0430 \u0432\u044b\u044f\u0432\u0438\u043b\u0438 \u043d\u043e\u0432\u044b\u0435 \u000d\u000a\u043c\u0438\u043d\u0435\u0440\u0430\u043b\u0438\u0437\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u0437\u043e\u043d\u044b. \u0412 \u0447\u0430\u0441\u0442\u043d\u043e\u0441\u0442\u0438, \u000d\u000a\u043d\u0430 \u0443\u0447\u0430\u0441\u0442\u043a\u0430\u0445 Jabal Shayban \u0438 Jabal Al Wakil \u000d\u000a\u043e\u0431\u043d\u0430\u0440\u0443\u0436\u0435\u043d\u044b \u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u044f \u043c\u0435\u0434\u0438, \u043d\u0438\u043a\u0435\u043b\u044f \u000d\u000a\u0438 \u043f\u043b\u0430\u0442\u0438\u043d\u044b.\u000d\u000a02 09","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a \u0438 \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 12\u201316 \u044f\u043d\u0432\u0430\u0440\u044f 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u043b\u043e\u0433\u0438\u0441\u0442\u0438\u043a\u0430 #\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b\u000d\u000aMaersk \u043f\u0440\u043e\u0432\u0435\u043b\u0430 \u0435\u0449\u0435 \u043e\u0434\u043d\u043e \u0441\u0443\u0434\u043d\u043e \u0447\u0435\u0440\u0435\u0437 \u041a\u0440\u0430\u0441\u043d\u043e\u0435 \u043c\u043e\u0440\u0435 \u000d\u000a\u043f\u043e\u0441\u043b\u0435 \u043f\u0440\u0435\u043a\u0440\u0430\u0449\u0435\u043d\u0438\u044f \u0431\u043e\u0435\u0432\u044b\u0445 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0439 \u0432 \u0413\u0430\u0437\u0435\u000d\u000a\u0415\u0449\u0435 \u043e\u0434\u043d\u043e \u0441\u0443\u0434\u043d\u043e \u0434\u0430\u0442\u0441\u043a\u043e\u0439 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 Maersk \u043f\u0440\u043e\u0448\u043b\u043e \u0447\u0435\u0440\u0435\u0437 \u0430\u043a\u0432\u0430\u0442\u043e\u0440\u0438\u044e \u041a\u0440\u0430\u0441\u043d\u043e\u0433\u043e \u043c\u043e\u0440\u044f \u043d\u0430 \u0444\u043e\u043d\u0435 \u000d\u000a\u043f\u0435\u0440\u0435\u043c\u0438\u0440\u0438\u044f \u0432 \u0441\u0435\u043a\u0442\u043e\u0440\u0435 \u0413\u0430\u0437\u0430, \u043a\u043e\u0442\u043e\u0440\u043e\u0435 \u0441\u043f\u043e\u0441\u043e\u0431\u0441\u0442\u0432\u0443\u0435\u0442 \u043f\u043e\u0441\u0442\u0435\u043f\u0435\u043d\u043d\u043e\u043c\u0443 \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u044e \u0442\u0440\u0430\u0444\u0438\u043a\u0430 \u000d\u000a\u0432 \u0440\u0435\u0433\u0438\u043e\u043d\u0435. \u000d\u000a\u0421\u0443\u0434\u043d\u043e Maersk Denver \u043f\u043e\u0434 \u0444\u043b\u0430\u0433\u043e\u043c \u0421\u0428\u0410 \u000d\u000a\u0443\u0441\u043f\u0435\u0448\u043d\u043e \u043f\u0435\u0440\u0435\u0441\u0435\u043a\u043b\u043e \u0411\u0430\u0431-\u044d\u043b\u044c-\u041c\u0430\u043d\u0434\u0435\u0431\u0441\u043a\u0438\u0439 \u000d\u000a\u043f\u0440\u043e\u043b\u0438\u0432 11 \u044f\u043d\u0432\u0430\u0440\u044f. \u041e\u0431 \u044d\u0442\u043e\u043c \u0433\u043e\u0432\u043e\u0440\u0438\u0442\u0441\u044f \u000d\u000a\u0432  \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438. \u00ab\u041c\u044b \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0438\u043c \u000d\u000a\u043f\u043e\u0441\u0442\u0435\u043f\u0435\u043d\u043d\u043e\u0435 \u0432\u043e\u0437\u043e\u0431\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u0435 \u043d\u0430\u0432\u0438\u0433\u0430\u0446\u0438\u0438 \u0447\u0435\u0440\u0435\u0437 \u000d\u000a\u0421\u0443\u044d\u0446\u043a\u0438\u0439 \u043a\u0430\u043d\u0430\u043b \u0438 \u041a\u0440\u0430\u0441\u043d\u043e\u0435 \u043c\u043e\u0440\u0435 \u043f\u0440\u0438 \u0443\u0441\u043b\u043e\u0432\u0438\u0438, \u000d\u000a\u0447\u0442\u043e \u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u044f \u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e\u0441\u0442\u0438 \u043f\u043e-\u043f\u0440\u0435\u0436\u043d\u0435\u043c\u0443 \u000d\u000a\u0431\u0443\u0434\u0443\u0442 \u0441\u043e\u0431\u043b\u044e\u0434\u0430\u0442\u044c\u0441\u044f\u00bb, \u2014 \u0434\u043e\u0431\u0430\u0432\u0438\u043b\u0430 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f.\u000d\u000a\u0437\u0430\u044f\u0432\u043b\u0435\u043d\u0438\u0438\u000d\u000a\u0422\u0440\u0430\u0444\u0438\u043a \u0447\u0435\u0440\u0435\u0437 \u0421\u0443\u044d\u0446\u043a\u0438\u0439 \u043a\u0430\u043d\u0430\u043b \u0432 \u043f\u0435\u0440\u0432\u0443\u044e \u043d\u0435\u0434\u0435\u043b\u044e \u000d\u000a\u044f\u043d\u0432\u0430\u0440\u044f \u043e\u0441\u0442\u0430\u0432\u0430\u043b\u0441\u044f \u043d\u0430 60% \u043d\u0438\u0436\u0435 \u0443\u0440\u043e\u0432\u043d\u044f \u2028\u000d\u000a2023 \u0433\u043e\u0434\u0430, \u043d\u0435\u0441\u043c\u043e\u0442\u0440\u044f \u043d\u0430 \u043f\u0435\u0440\u0432\u044b\u0435 \u043f\u0440\u0438\u0437\u043d\u0430\u043a\u0438 \u000d\u000a\u0432\u043e\u0437\u0432\u0440\u0430\u0449\u0435\u043d\u0438\u044f \u043d\u0430 \u044d\u0442\u043e\u0442 \u043c\u0430\u0440\u0448\u0440\u0443\u0442 \u043a\u0440\u0443\u043f\u043d\u044b\u0445 \u000d\u000a\u0441\u0443\u0434\u043e\u0445\u043e\u0434\u043d\u044b\u0445 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0439. \u000d\u000a#\u043b\u043e\u0433\u0438\u0441\u0442\u0438\u043a\u0430\u000d\u000a\u0421\u043e\u043c\u0430\u043b\u0438 \u0430\u043d\u043d\u0443\u043b\u0438\u0440\u043e\u0432\u0430\u043b\u0430 \u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u044f \u0441 \u041e\u0410\u042d \u2028\u000d\u000a\u043e \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u0438 \u043f\u043e\u0440\u0442\u043e\u0432\u043e\u0439 \u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u044b\u000d\u000a\u041f\u043e\u0432\u043e\u0434\u043e\u043c \u0434\u043b\u044f \u044d\u0442\u043e\u0433\u043e \u0441\u0442\u0430\u043b\u043e \u0437\u0430\u044f\u0432\u043b\u0435\u043d\u0438\u0435 \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0439 \u0410\u0440\u0430\u0432\u0438\u0438, \u0441\u043e\u0433\u043b\u0430\u0441\u043d\u043e \u043a\u043e\u0442\u043e\u0440\u043e\u043c\u0443 \u041e\u0410\u042d \u0432\u044b\u0432\u0435\u0437\u043b\u0438 \u000d\u000a\u043b\u0438\u0434\u0435\u0440\u0430 \u0439\u0435\u043c\u0435\u043d\u0441\u043a\u0438\u0445 \u0441\u0435\u043f\u0430\u0440\u0430\u0442\u0438\u0441\u0442\u043e\u0432 \u0447\u0435\u0440\u0435\u0437 \u0442\u0435\u0440\u0440\u0438\u0442\u043e\u0440\u0438\u044e \u0421\u043e\u043c\u0430\u043b\u0438.\u000d\u000a\u0412\u043b\u0430\u0441\u0442\u0438 \u0421\u043e\u043c\u0430\u043b\u0438 \u0430\u043d\u043d\u0443\u043b\u0438\u0440\u043e\u0432\u0430\u043b\u0438 \u0432\u0441\u0435 \u000d\u000a\u043a\u043e\u043c\u043c\u0435\u0440\u0447\u0435\u0441\u043a\u0438\u0435 \u0438 \u043e\u0431\u043e\u0440\u043e\u043d\u043d\u044b\u0435 \u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u044f \u000d\u000a\u0441 \u041e\u0410\u042d, \u0432\u043a\u043b\u044e\u0447\u0430\u044f \u0438\u043d\u0432\u0435\u0441\u0442\u043f\u0440\u043e\u0435\u043a\u0442\u044b \u0432 \u043f\u043e\u0440\u0442\u044b. \u000d\u000a\u041e\u0431 \u044d\u0442\u043e\u043c \u043f\u0440\u0435\u0441\u0441-\u0441\u043b\u0443\u0436\u0431\u0430 \u000d\u000a\u0441\u043e\u043c\u0430\u043b\u0438\u0439\u0441\u043a\u043e\u0433\u043e \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0430. \u000a\u000d\u000a\u0420\u0435\u0448\u0435\u043d\u0438\u0435 \u0437\u0430\u0442\u0440\u0430\u0433\u0438\u0432\u0430\u0435\u0442 \u043f\u043e\u0440\u0442\u044b \u0411\u0435\u0440\u0431\u0435\u0440\u0430, \u2028\u000d\u000a\u0411\u043e\u0441\u0430\u0441\u043e \u0438 \u041a\u0438\u0441\u043c\u0430\u0439\u043e. \u041f\u0435\u0440\u0432\u044b\u0435 \u0434\u0432\u0430 \u0440\u0430\u0441\u043f\u043e\u043b\u043e\u0436\u0435\u043d\u044b \u000d\u000a\u043d\u0430 \u043f\u043e\u0431\u0435\u0440\u0435\u0436\u044c\u0435 \u0410\u0434\u0435\u043d\u0441\u043a\u043e\u0433\u043e \u0437\u0430\u043b\u0438\u0432\u0430, \u0442\u0440\u0435\u0442\u0438\u0439 \u2014 \u000d\u000a\u043d\u0430 \u043f\u043e\u0431\u0435\u0440\u0435\u0436\u044c\u0435 \u0418\u043d\u0434\u0438\u0439\u0441\u043a\u043e\u0433\u043e \u043e\u043a\u0435\u0430\u043d\u0430. \u041f\u043e\u0440\u0442 \u000d\u000a\u0411\u0435\u0440\u0431\u0435\u0440\u0430 \u043d\u0430\u0445\u043e\u0434\u0438\u0442\u0441\u044f \u043d\u0430 \u0442\u0435\u0440\u0440\u0438\u0442\u043e\u0440\u0438\u0438 \u000d\u000a\u043d\u0435\u043f\u0440\u0438\u0437\u043d\u0430\u043d\u043d\u043e\u0439 \u0440\u0435\u0441\u043f\u0443\u0431\u043b\u0438\u043a\u0438 \u0421\u043e\u043c\u0430\u043b\u0438\u043b\u0435\u043d\u0434.\u000a\u000d\u000aDP World \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0440\u043e\u0432\u0430\u043b\u0430 \u0441\u043e\u0442\u043d\u0438 \u043c\u0438\u043b\u043b\u0438\u043e\u043d\u043e\u0432 \u000d\u000a\u0434\u043e\u043b\u043b\u0430\u0440\u043e\u0432 \u0432 \u043c\u043e\u0434\u0435\u0440\u043d\u0438\u0437\u0430\u0446\u0438\u044e \u0441\u043e\u043c\u0430\u043b\u0438\u0439\u0441\u043a\u0438\u0445 \u000d\u000a\u0441\u043e\u043e\u0431\u0449\u0438\u043b\u0430\u000d\u000a\u043f\u043e\u0440\u0442\u043e\u0432 \u043d\u0430 \u043e\u0434\u043d\u043e\u043c \u0438\u0437 \u043a\u043b\u044e\u0447\u0435\u0432\u044b\u0445 \u0442\u043e\u0440\u0433\u043e\u0432\u044b\u0445 \u000d\u000a\u043c\u0430\u0440\u0448\u0440\u0443\u0442\u043e\u0432.\u000d\u000a03 09","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a \u0438 \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 12\u201316 \u044f\u043d\u0432\u0430\u0440\u044f 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u044d\u043d\u0435\u0440\u0433\u0435\u0442\u0438\u043a\u0430\u000d\u000aTotalEnergies \u0441\u043e\u0437\u0434\u0430\u0435\u0442 \u0441\u043e\u0432\u043c\u0435\u0441\u0442\u043d\u043e\u0435 \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u0435 \u2028\u000d\u000a\u0441 \u0431\u0430\u0445\u0440\u0435\u0439\u043d\u0441\u043a\u043e\u0439 Bapco Energies\u000d\u000a\u041f\u0430\u0440\u0442\u043d\u0435\u0440\u0441\u0442\u0432\u043e \u0440\u0430\u0437\u0432\u0438\u0432\u0430\u0435\u0442 \u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u0435 2024 \u0433\u043e\u0434\u0430, \u043f\u043e \u043a\u043e\u0442\u043e\u0440\u043e\u043c\u0443 TotalEnergies \u043e\u0431\u044f\u0437\u0430\u043b\u0430\u0441\u044c \u000d\u000a\u0441\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u043e\u0432\u0430\u0442\u044c \u043c\u043e\u0434\u0435\u0440\u043d\u0438\u0437\u0430\u0446\u0438\u0438 \u043d\u0435\u0444\u0442\u0435\u043f\u0435\u0440\u0435\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u044e\u0449\u0435\u0433\u043e \u0437\u0430\u0432\u043e\u0434\u0430 Sitra. \u0415\u0433\u043e \u043f\u0440\u043e\u0435\u043a\u0442\u043d\u0430\u044f \u000d\u000a\u043c\u043e\u0449\u043d\u043e\u0441\u0442\u044c \u2014 405 \u0442\u044b\u0441. \u0431\u0430\u0440\u0440\u0435\u043b\u0435\u0439 \u0432 \u0441\u0443\u0442\u043a\u0438.\u000d\u000a\u0424\u0440\u0430\u043d\u0446\u0443\u0437\u0441\u043a\u0430\u044f \u043d\u0435\u0444\u0442\u0435\u0433\u0430\u0437\u043e\u0432\u0430\u044f \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u000d\u000aTotalEnergies \u043e \u0441\u043e\u0437\u0434\u0430\u043d\u0438\u0438 \u000d\u000a\u0441\u043e\u0432\u043c\u0435\u0441\u0442\u043d\u043e\u0433\u043e \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u044f \u0441 \u0431\u0430\u0445\u0440\u0435\u0439\u043d\u0441\u043a\u043e\u0439 \u000d\u000aBapco Energies. \u041d\u043e\u0432\u0430\u044f \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0430 BxT Trading \u000d\u000a\u0431\u0443\u0434\u0435\u0442 \u043f\u0440\u0438\u043d\u0430\u0434\u043b\u0435\u0436\u0430\u0442\u044c \u043f\u0430\u0440\u0442\u043d\u0435\u0440\u0430\u043c \u043d\u0430 \u043f\u0430\u0440\u0438\u0442\u0435\u0442\u043d\u043e\u0439 \u000d\u000a\u043e\u0441\u043d\u043e\u0432\u0435.\u000d\u000a\u043e\u0431\u044a\u044f\u0432\u0438\u043b\u0430\u000d\u000a\u041f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u0435 \u0441\u043e\u0441\u0440\u0435\u0434\u043e\u0442\u043e\u0447\u0438\u0442\u0441\u044f \u043d\u0430 \u0442\u043e\u0440\u0433\u043e\u0432\u043b\u0435 \u000d\u000a\u043f\u0440\u043e\u0434\u0443\u043a\u0446\u0438\u0435\u0439 \u043d\u0435\u0444\u0442\u0435\u043f\u0435\u0440\u0435\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u044e\u0449\u0435\u0433\u043e \u0437\u0430\u0432\u043e\u0434\u0430 \u000d\u000aSitra, \u043f\u0440\u0438\u043d\u0430\u0434\u043b\u0435\u0436\u0430\u0449\u0435\u0433\u043e Bapco, \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u044c\u044e \u2028\u000d\u000a267 \u0442\u044b\u0441. \u0431\u0430\u0440\u0440\u0435\u043b\u0435\u0439 \u0432 \u0441\u0443\u0442\u043a\u0438. \u000d\u000a#\u044d\u043d\u0435\u0440\u0433\u0435\u0442\u0438\u043a\u0430\u000d\u000aBapco Energies \u0432\u043f\u0435\u0440\u0432\u044b\u0435 \u0437\u0430 2,5 \u0433\u043e\u0434\u0430 \u043e\u0442\u043f\u0440\u0430\u0432\u0438\u043b\u0430 \u000d\u000a\u043f\u0430\u0440\u0442\u0438\u044e \u0434\u0438\u0437\u0435\u043b\u044f \u0432 \u0410\u0432\u0441\u0442\u0440\u0430\u043b\u0438\u044e\u000d\u000a\u042d\u043a\u0441\u043f\u043e\u0440\u0442 \u0431\u0430\u0445\u0440\u0435\u0439\u043d\u0441\u043a\u043e\u0433\u043e \u0442\u043e\u043f\u043b\u0438\u0432\u0430 \u0432 \u0410\u0432\u0441\u0442\u0440\u0430\u043b\u0438\u044e \u0432\u043e\u0437\u043e\u0431\u043d\u043e\u0432\u0438\u043b\u0441\u044f \u043d\u0430 \u0444\u043e\u043d\u0435 \u043d\u0430\u0440\u0430\u0449\u0438\u0432\u0430\u043d\u0438\u044f \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u043d\u0435\u0444\u0442\u0435\u043f\u0435\u0440\u0435\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u044e\u0449\u0438\u043c \u0437\u0430\u0432\u043e\u0434\u043e\u043c Sitra.\u000d\u000a\u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0441\u043a\u0430\u044f Bapco Energies \u043e\u0442\u043f\u0440\u0430\u0432\u0438\u043b\u0430 \u000d\u000a\u043f\u0435\u0440\u0432\u0443\u044e \u0437\u0430 \u043f\u043e\u0447\u0442\u0438 \u0434\u0432\u0430 \u0441 \u043f\u043e\u043b\u043e\u0432\u0438\u043d\u043e\u0439 \u0433\u043e\u0434\u0430 \u000d\u000a\u043f\u0430\u0440\u0442\u0438\u044e \u0434\u0438\u0437\u0435\u043b\u044c\u043d\u043e\u0433\u043e \u0442\u043e\u043f\u043b\u0438\u0432\u0430 \u0432 \u0410\u0432\u0441\u0442\u0440\u0430\u043b\u0438\u044e. \u2028\u000d\u000a\u041e\u0431 \u044d\u0442\u043e\u043c Reuters. \u000a\u000d\u000a\u041e\u043a\u043e\u043b\u043e 400 \u0442\u044b\u0441. \u0431\u0430\u0440\u0440\u0435\u043b\u0435\u0439 \u0434\u0438\u0437\u0435\u043b\u044f \u0431\u044b\u043b\u0438 \u000d\u000a\u043f\u043e\u0433\u0440\u0443\u0436\u0435\u043d\u044b \u043d\u0430 \u0442\u0430\u043d\u043a\u0435\u0440 Torm Kirsten \u000d\u000a\u043d\u0430 \u043d\u0435\u0444\u0442\u0435\u043f\u0435\u0440\u0435\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u044e\u0449\u0435\u043c \u0437\u0430\u0432\u043e\u0434\u0435 Sitra\u000d\u000a\u0441\u043e\u043e\u0431\u0449\u0438\u043b\u043e\u000d\u000a\u0432 \u043f\u0435\u0440\u0438\u043e\u0434 \u0441 9 \u043f\u043e 11 \u0434\u0435\u043a\u0430\u0431\u0440\u044f. \u0415\u0449\u0435 \u043e\u043a\u043e\u043b\u043e \u2028\u000d\u000a140 \u0442\u044b\u0441. \u0431\u0430\u0440\u0440\u0435\u043b\u0435\u0439 \u0431\u044b\u043b\u0438 \u0437\u0430\u0433\u0440\u0443\u0436\u0435\u043d\u044b \u0447\u0435\u0440\u0435\u0437 \u000d\u000a\u043f\u0435\u0440\u0435\u0432\u0430\u043b\u043a\u0443 \u00ab\u0431\u043e\u0440\u0442 \u0432 \u0431\u043e\u0440\u0442\u00bb \u0441 \u0442\u0430\u043d\u043a\u0435\u0440\u0430 Zonda.\u000a\u000d\u000a\u0421\u0443\u0434\u043d\u043e \u0437\u0430\u0444\u0440\u0430\u0445\u0442\u043e\u0432\u0430\u043d\u043e \u0442\u0440\u0430\u043d\u0441\u043f\u043e\u0440\u0442\u043d\u044b\u043c \u000d\u000a\u043f\u043e\u0434\u0440\u0430\u0437\u0434\u0435\u043b\u0435\u043d\u0438\u0435\u043c TotalEnergies, \u043a\u043e\u0442\u043e\u0440\u0430\u044f \u043f\u043e\u0441\u043b\u0435 \u000d\u000a\u0441\u0434\u0435\u043b\u043a\u0438 2024 \u0433\u043e\u0434\u0430 \u0432\u0435\u0434\u0435\u0442 \u043e\u0441\u043d\u043e\u0432\u043d\u0443\u044e \u0447\u0430\u0441\u0442\u044c \u000d\u000a\u044d\u043a\u0441\u043f\u043e\u0440\u0442\u043d\u044b\u0445 \u043f\u0440\u043e\u0434\u0430\u0436 Bapco.\u000d\u000a04 09","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a \u0438 \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 12\u201316 \u044f\u043d\u0432\u0430\u0440\u044f 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u0442\u0435\u0445\u043d\u043e\u043b\u043e\u0433\u0438\u0438\u000d\u000a\u0412\u043b\u0430\u0441\u0442\u0438 \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0430 \u043e\u0434\u043e\u0431\u0440\u0438\u043b\u0438 \u0437\u0430\u043f\u0443\u0441\u043a \u2028\u000d\u000a\u0441\u043f\u0443\u0442\u043d\u0438\u043a\u043e\u0432\u043e\u0433\u043e \u0438\u043d\u0442\u0435\u0440\u043d\u0435\u0442\u0430 Starlink\u000d\u000a\u041f\u0440\u043e\u0432\u0430\u0439\u0434\u0435\u0440 \u043d\u0430\u0440\u0430\u0449\u0438\u0432\u0430\u0435\u0442 \u043f\u0440\u0438\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u0435 \u043d\u0430 \u0411\u043b\u0438\u0436\u043d\u0435\u043c \u0412\u043e\u0441\u0442\u043e\u043a\u0435 \u0432 \u0443\u0441\u043b\u043e\u0432\u0438\u044f\u0445 \u0443\u0432\u0435\u043b\u0438\u0447\u0435\u043d\u0438\u044f \u000d\u000a\u043a\u043e\u043d\u043a\u0443\u0440\u0435\u043d\u0446\u0438\u0438 \u0432 \u0441\u043f\u0443\u0442\u043d\u0438\u043a\u043e\u0432\u043e\u0439 \u0441\u0432\u044f\u0437\u0438. \u041e\u043c\u0430\u043d \u0438 \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0430\u044f \u0410\u0440\u0430\u0432\u0438\u044f \u0443\u0436\u0435 \u043f\u0443\u0441\u0442\u0438\u043b\u0438 Starlink \u2028\u000d\u000a\u043d\u0430 \u0441\u0432\u043e\u0438 \u0440\u044b\u043d\u043a\u0438.\u000d\u000a\u0423\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u043f\u043e \u0440\u0435\u0433\u0443\u043b\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044e \u000d\u000a\u0442\u0435\u043b\u0435\u043a\u043e\u043c\u043c\u0443\u043d\u0438\u043a\u0430\u0446\u0438\u0439 \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0430 \u0437\u0430\u043f\u0443\u0441\u043a \u000d\u000a\u0441\u0435\u0440\u0432\u0438\u0441\u0430 \u0441\u043f\u0443\u0442\u043d\u0438\u043a\u043e\u0432\u043e\u0433\u043e \u0438\u043d\u0442\u0435\u0440\u043d\u0435\u0442\u0430 Starlink, \u000d\u000a\u043f\u0440\u0438\u043d\u0430\u0434\u043b\u0435\u0436\u0430\u0449\u0435\u0433\u043e \u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u043e\u043c\u0443 \u000d\u000a\u043f\u0440\u0435\u0434\u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0442\u0435\u043b\u044e \u0418\u043b\u043e\u043d\u0443 \u041c\u0430\u0441\u043a\u0443. \u000a\u000d\u000a\u041e\u043a\u0430\u0437\u044b\u0432\u0430\u0442\u044c \u0443\u0441\u043b\u0443\u0433\u0438 \u0431\u0443\u0434\u0435\u0442 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f Sama X \u2014 \u000d\u000a\u0430\u0432\u0442\u043e\u0440\u0438\u0437\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u0433\u043b\u043e\u0431\u0430\u043b\u044c\u043d\u044b\u0439 \u0440\u0435\u0441\u0435\u043b\u043b\u0435\u0440 Starlink, \u000d\u000a\u043e\u0434\u043e\u0431\u0440\u0438\u043b\u043e\u000d\u000a\u043f\u043e\u043b\u0443\u0447\u0438\u0432\u0448\u0438\u0439 \u043b\u0438\u0446\u0435\u043d\u0437\u0438\u044e \u0440\u0435\u0433\u0443\u043b\u044f\u0442\u043e\u0440\u0430. \u000d\u000a\u0412\u044b\u0441\u043e\u043a\u043e\u0441\u043a\u043e\u0440\u043e\u0441\u0442\u043d\u043e\u0439 \u0438\u043d\u0442\u0435\u0440\u043d\u0435\u0442 \u0431\u0443\u0434\u0435\u0442 \u0434\u043e\u0441\u0442\u0443\u043f\u0435\u043d \u000d\u000a\u043f\u043e \u0432\u0441\u0435\u0439 \u0442\u0435\u0440\u0440\u0438\u0442\u043e\u0440\u0438\u0438 \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0430, \u0432\u043a\u043b\u044e\u0447\u0430\u044f \u000d\u000a\u043d\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u044b\u0435 \u0432\u043e\u0434\u044b.\u000a\u000d\u000aSama X \u043f\u0440\u0438\u043d\u0430\u0434\u043b\u0435\u0436\u0438\u0442 \u043a\u0443\u0432\u0435\u0439\u0442\u0441\u043a\u043e\u0439 \u0433\u0440\u0443\u043f\u043f\u0435 \u000d\u000aAlghanim Industries, \u043a\u043e\u0442\u043e\u0440\u0430\u044f \u0443\u0436\u0435 \u043f\u0440\u0435\u0434\u043b\u0430\u0433\u0430\u0435\u0442 \u000d\u000a\u0443\u0441\u043b\u0443\u0433\u0438 Starlink \u0432 \u041a\u0443\u0432\u0435\u0439\u0442\u0435.\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u041e\u043c\u0430\u043d \u043f\u0440\u0438\u0432\u043b\u0435\u043a $400 \u043c\u043b\u043d \u043d\u0430 \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u0435 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0435\u0433\u043e \u000d\u000a\u043c\u0435\u0434\u043d\u043e\u0433\u043e \u043f\u0440\u043e\u0435\u043a\u0442\u0430 Mazoon\u000d\u000a\u0426\u0435\u043d\u044b \u043d\u0430 \u043c\u0435\u0434\u044c \u0437\u0430 \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0438\u0439 \u0433\u043e\u0434 \u0432\u044b\u0440\u043e\u0441\u043b\u0438 \u043d\u0430 30%. \u0422\u0440\u0435\u043d\u0434 \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0435\u0442 \u0441\u0442\u0438\u043c\u0443\u043b\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435 \u000d\u000a\u0441\u043f\u0440\u043e\u0441\u0430 \u0432 \u041a\u0438\u0442\u0430\u0435 \u0438 \u0441\u043e\u043a\u0440\u0430\u0449\u0435\u043d\u0438\u0435 \u0434\u043e\u0431\u044b\u0447\u0438 \u0443 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0445 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u0435\u0439.\u000d\u000a\u041e\u043c\u0430\u043d $400 \u043c\u043b\u043d \u0434\u043b\u044f \u0441\u0432\u043e\u0435\u0433\u043e \u000d\u000a\u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0435\u0433\u043e \u0433\u043e\u0440\u043d\u043e\u0434\u043e\u0431\u044b\u0432\u0430\u044e\u0449\u0435\u0433\u043e \u043f\u0440\u043e\u0435\u043a\u0442\u0430 \u000d\u000a\u043f\u043e \u0434\u043e\u0431\u044b\u0447\u0435 \u043c\u0435\u0434\u0438. \u041e\u0431 \u044d\u0442\u043e\u043c \u0441\u043e\u043e\u0431\u0449\u0438\u043b \u043a\u0430\u0442\u0430\u0440\u0441\u043a\u0438\u0439 \u000d\u000a\u0431\u0430\u043d\u043a Ahlibank, \u0432\u044b\u0434\u0430\u0432\u0448\u0438\u0439 \u043a\u0440\u0435\u0434\u0438\u0442 \u0434\u043b\u044f \u043e\u043c\u0430\u043d\u0441\u043a\u043e\u0439 \u000d\u000a\u0433\u043e\u0440\u043d\u043e\u0434\u043e\u0431\u044b\u0432\u0430\u044e\u0449\u0435\u0439 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 MDO.\u000a\u000d\u000a\u0421\u0440\u0435\u0434\u0441\u0442\u0432\u0430 \u0431\u0443\u0434\u0443\u0442 \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u044b \u043d\u0430 \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u0435 \u000d\u000a\u043f\u0440\u043e\u0435\u043a\u0442\u0430 Mazoon \u0432 \u0440\u0430\u0439\u043e\u043d\u0435 \u042f\u043d\u043a\u0443\u043b\u044c \u043d\u0430 \u0441\u0435\u0432\u0435\u0440\u043e\u000d\u000a\u0437\u0430\u043f\u0430\u0434\u0435 \u0441\u0442\u0440\u0430\u043d\u044b. \u041f\u043b\u043e\u0449\u0430\u0434\u044c \u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u044f, \u000d\u000a\u0437\u0430\u043f\u0430\u0441\u044b \u043a\u043e\u0442\u043e\u0440\u043e\u0433\u043e \u043e\u0446\u0435\u043d\u0438\u0432\u0430\u044e\u0442\u0441\u044f \u0432 22,9 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u000d\u000a\u0440\u0443\u0434\u044b, \u0441\u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0435\u0442 \u043e\u043a\u043e\u043b\u043e 20 \u043a\u043c2. \u041f\u0440\u043e\u0435\u043a\u0442 \u000d\u000a\u043f\u0440\u0438\u0432\u043b\u0435\u043a \u043f\u0440\u0435\u0434\u0443\u0441\u043c\u0430\u0442\u0440\u0438\u0432\u0430\u0435\u0442 \u0432\u044b\u043f\u0443\u0441\u043a 115 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d \u043c\u0435\u0434\u043d\u043e\u0433\u043e \u000d\u000a\u043a\u043e\u043d\u0446\u0435\u043d\u0442\u0440\u0430\u0442\u0430 \u0435\u0436\u0435\u0433\u043e\u0434\u043d\u043e \u0441 \u0441\u043e\u0434\u0435\u0440\u0436\u0430\u043d\u0438\u0435\u043c \u043c\u0435\u0434\u0438 \u000d\u000a21,5%.\u000a\u000d\u000a\u0412 \u043c\u0430\u0435 2025 \u0433\u043e\u0434\u0430 \u0434\u043e\u0447\u0435\u0440\u043d\u044f\u044f \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0430 MDO \u2014 \u000d\u000a\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f Mazoon Mining \u2014 \u0443\u0436\u0435 \u043f\u0440\u0438\u0432\u043b\u0435\u043a\u043b\u0430 \u000d\u000a$270 \u043c\u043b\u043d \u043e\u0442 \u043c\u0435\u0441\u0442\u043d\u044b\u0445 \u0438 \u0440\u0435\u0433\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u044b\u0445 \u0431\u0430\u043d\u043a\u043e\u0432, \u000d\u000a\u0430 \u0442\u0430\u043a\u0436\u0435 \u043f\u043e\u0434\u043f\u0438\u0441\u0430\u043b\u0430 \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u043a\u043e\u043d\u0442\u0440\u0430\u043a\u0442\u043e\u0432 \u000d\u000a\u0441 \u043e\u043c\u0430\u043d\u0441\u043a\u0438\u043c\u0438 \u043f\u043e\u0434\u0440\u044f\u0434\u0447\u0438\u043a\u0430\u043c\u0438 \u043d\u0430 \u0441\u0442\u0440\u043e\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u000d\u000a\u0438 \u043e\u0431\u0441\u043b\u0443\u0436\u0438\u0432\u0430\u043d\u0438\u0435 \u043e\u0431\u044a\u0435\u043a\u0442\u043e\u0432.\u000d\u000a05 09","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a \u0438 \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 12\u201316 \u044f\u043d\u0432\u0430\u0440\u044f 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000aPIF \u0432\u044b\u0434\u0435\u043b\u0438\u0442 Manara Minerals \u0432 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u0443\u044e \u000d\u000a\u0433\u043e\u0440\u043d\u043e\u0434\u043e\u0431\u044b\u0432\u0430\u044e\u0449\u0443\u044e \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0443\u000d\u000aManara Minerals \u0441\u043e\u0437\u0434\u0430\u043d\u0430 \u0432 2023 \u0433\u043e\u0434\u0443 \u0434\u043b\u044f \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0439 \u0432 \u0441\u0435\u043a\u0442\u043e\u0440 \u043a\u0440\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u0432\u0430\u0436\u043d\u044b\u0445 \u043f\u043e\u043b\u0435\u0437\u043d\u044b\u0445 \u000d\u000a\u0438\u0441\u043a\u043e\u043f\u0430\u0435\u043c\u044b\u0445 \u0437\u0430 \u0440\u0443\u0431\u0435\u0436\u043e\u043c. \u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u0432\u043b\u0430\u0434\u0435\u0435\u0442 \u0434\u043e\u043b\u0435\u0439 10% \u0432 \u0434\u043e\u0447\u0435\u0440\u043d\u0435\u0439 \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0435 \u0431\u0440\u0430\u0437\u0438\u043b\u044c\u0441\u043a\u043e\u0433\u043e \u000d\u000a\u0433\u043e\u0440\u043d\u043e\u0434\u043e\u0431\u044b\u0442\u0447\u0438\u043a\u0430 Vale.\u000d\u000a\u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0438\u0439 \u0441\u0443\u0432\u0435\u0440\u0435\u043d\u043d\u044b\u0439 \u0444\u043e\u043d\u0434 Public \u000d\u000aInvestment Fund (PIF) \u043f\u043b\u0430\u043d\u0438\u0440\u0443\u0435\u0442 \u0432\u044b\u0434\u0435\u043b\u0438\u0442\u044c \u000d\u000a\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044e Manara Minerals, \u0441\u043e\u0437\u0434\u0430\u043d\u043d\u0443\u044e \u000d\u000a\u0441\u043e\u0432\u043c\u0435\u0441\u0442\u043d\u043e \u0441 \u0433\u043e\u0440\u043d\u043e\u0434\u043e\u0431\u044b\u0432\u0430\u044e\u0449\u0435\u0439 \u000d\u000a\u0433\u043e\u0441\u043a\u043e\u0440\u043f\u043e\u0440\u0430\u0446\u0438\u0435\u0439 Maaden, \u0432 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u0443\u044e \u000d\u000a\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0443. \u041e\u0431 \u044d\u0442\u043e\u043c Reuters \u043c\u0438\u043d\u0438\u0441\u0442\u0440 \u000d\u000a\u043f\u0440\u043e\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u043e\u0441\u0442\u0438 \u0438 \u043c\u0438\u043d\u0435\u0440\u0430\u043b\u044c\u043d\u044b\u0445 \u0440\u0435\u0441\u0443\u0440\u0441\u043e\u0432 \u000d\u000a\u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0441\u0442\u0432\u0430 \u0411\u0430\u043d\u0434\u0430\u0440 \u0430\u043b\u044c-\u0425\u0443\u0440\u0435\u0439\u0444.\u000d\u000a\u0441\u043e\u043e\u0431\u0449\u0438\u043b\u000d\u000a\u0422\u0430\u043a\u043e\u0435 \u0440\u0435\u0448\u0435\u043d\u0438\u0435 \u043f\u043e\u0437\u0432\u043e\u043b\u0438\u0442 Manara Minerals \u000d\u000a\u043f\u0435\u0440\u0435\u0439\u0442\u0438 \u043e\u0442 \u0440\u043e\u043b\u0438 \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u043e\u043d\u043d\u043e\u0433\u043e \u0438\u043d\u0441\u0442\u0440\u0443\u043c\u0435\u043d\u0442\u0430 \u000d\u000a\u043a \u0444\u043e\u0440\u043c\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044e \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0445 \u0442\u0435\u0445\u043d\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u000d\u000a\u0438 \u043e\u0442\u0440\u0430\u0441\u043b\u0435\u0432\u044b\u0445 \u043a\u043e\u043c\u043f\u0435\u0442\u0435\u043d\u0446\u0438\u0439. \u0420\u0443\u043a\u043e\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u000d\u000a\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0430\u0435\u0442 \u043e\u0431\u0441\u0443\u0436\u0434\u0430\u0442\u044c \u043f\u0440\u0438\u0432\u043b\u0435\u0447\u0435\u043d\u0438\u0435 \u000d\u000a\u043d\u043e\u0432\u044b\u0445 \u0430\u043a\u0446\u0438\u043e\u043d\u0435\u0440\u043e\u0432 \u2014 \u043a\u0430\u043a \u0441\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0438\u0445, \u0442\u0430\u043a \u000d\u000a\u0438 \u0438\u043d\u043e\u0441\u0442\u0440\u0430\u043d\u043d\u044b\u0445.\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000aGecamines \u043f\u0440\u0438\u043e\u0431\u0440\u0435\u0442\u0435\u0442 100 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d \u043c\u0435\u0434\u0438 \u2028\u000d\u000a\u0441 \u0440\u0443\u0434\u043d\u0438\u043a\u0430 \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u043e\u0439 CMOC \u0432 \u041a\u043e\u043d\u0433\u043e\u000d\u000a\u041c\u0435\u0442\u0430\u043b\u043b \u0431\u0443\u0434\u0435\u0442 \u043f\u043e\u0441\u0442\u0430\u0432\u043b\u0435\u043d \u043d\u0430 \u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u0438\u0439 \u0440\u044b\u043d\u043e\u043a.\u000d\u000a\u0413\u043e\u0441\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u0414\u0435\u043c\u043e\u043a\u0440\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u0420\u0435\u0441\u043f\u0443\u0431\u043b\u0438\u043a\u0438 \u000d\u000a\u041a\u043e\u043d\u0433\u043e (\u0414\u0420\u041a) Gecamines \u043e \u043f\u043b\u0430\u043d\u0430\u0445 \u000d\u000a\u043f\u0440\u0438\u043e\u0431\u0440\u0435\u0441\u0442\u0438 100 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d \u043c\u0435\u0434\u0438 \u0441 \u0440\u0443\u0434\u043d\u0438\u043a\u0430 \u000d\u000a\u0422\u0435\u043d\u043a\u0435-\u0424\u0443\u043d\u0433\u0443\u0440\u0443\u043c\u0435 \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u043e\u0439 China Molybdenum \u000d\u000a(CMOC Group).\u000a\u000d\u000a\u042d\u0442\u043e\u0442 \u043e\u0431\u044a\u0435\u043c \u0441\u043e\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u0435\u0442 20% \u0433\u043e\u0434\u043e\u0432\u043e\u0433\u043e \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u044f \u0438 20-\u043f\u0440\u043e\u0446\u0435\u043d\u0442\u043d\u043e\u0439 \u000d\u000a\u0436\u0435 \u0434\u043e\u043b\u0435 Gecamines \u0432 \u043f\u0440\u043e\u0435\u043a\u0442\u0435. \u0413\u043e\u0441\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u000d\u000a\u0443\u043a\u0430\u0437\u0430\u043b\u0430, \u0447\u0442\u043e \u0443\u043a\u0430\u0437\u0430\u043d\u043d\u044b\u0439 \u043e\u0431\u044a\u0435\u043c \u043c\u0435\u0434\u0438 \u0431\u0443\u0434\u0435\u0442 \u000d\u000a\u0440\u0435\u0430\u043b\u0438\u0437\u043e\u0432\u0430\u043d \u0432 \u0421\u0428\u0410. \u0424\u0438\u043d\u0430\u043d\u0441\u043e\u0432\u0443\u044e, \u000d\u000a\u0441\u043e\u043e\u0431\u0449\u0438\u043b\u0430\u000d\u000a\u043b\u043e\u0433\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0443\u044e \u0438 \u0442\u0435\u0445\u043d\u0438\u0447\u0435\u0441\u043a\u0443\u044e \u043f\u043e\u043c\u043e\u0449\u044c \u0435\u0439 \u0431\u0443\u0434\u0435\u0442 \u000d\u000a\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0442\u044c \u0448\u0432\u0435\u0439\u0446\u0430\u0440\u0441\u043a\u0438\u0439 \u0442\u0440\u0435\u0439\u0434\u0435\u0440 Mercuria.\u000d\u000a06 09","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a \u0438 \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 12\u201316 \u044f\u043d\u0432\u0430\u0440\u044f 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u041a\u0438\u0442\u0430\u0439 \u0438 \u0410\u0437\u0438\u044f \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0430\u0442 \u043e\u043a\u043e\u043b\u043e 60% \u0440\u043e\u0441\u0442\u0430 \u043c\u0438\u0440\u043e\u0432\u043e\u0433\u043e \u000d\u000a\u0441\u043f\u0440\u043e\u0441\u0430 \u043d\u0430 \u043c\u0435\u0434\u044c \u0434\u043e 2040 \u0433\u043e\u0434\u0430\u000d\u000a\u0414\u0440\u0443\u0433\u0438\u043c\u0438 \u043b\u0438\u0434\u0435\u0440\u0430\u043c\u0438 \u0441\u0442\u0430\u043d\u0443\u0442 \u0441\u0442\u0440\u0430\u043d\u044b \u0410\u0422\u0420 \u0438 \u0415\u0432\u0440\u043e\u043f\u044b.\u000d\u000a\u041d\u0430 \u041a\u041d\u0420 \u0438 \u0434\u0440\u0443\u0433\u0438\u0435 \u0441\u0442\u0440\u0430\u043d\u044b \u0430\u0437\u0438\u0430\u0442\u0441\u043a\u043e\u0433\u043e \u0440\u0435\u0433\u0438\u043e\u043d\u0430 \u000d\u000a\u0431\u0443\u0434\u0435\u0442 \u043f\u0440\u0438\u0445\u043e\u0434\u0438\u0442\u044c\u0441\u044f \u043e\u043a\u043e\u043b\u043e 60% \u0440\u043e\u0441\u0442\u0430 \u043c\u0438\u0440\u043e\u0432\u043e\u0433\u043e \u000d\u000a\u0441\u043f\u0440\u043e\u0441\u0430 \u043d\u0430 \u043c\u0435\u0434\u044c \u0432 \u043f\u0435\u0440\u0438\u043e\u0434 \u0441 2025 \u043f\u043e 2040 \u0433\u043e\u0434, \u000d\u000a \u0432 \u0434\u043e\u043a\u043b\u0430\u0434\u0435 S&P Global.\u000a\u000d\u000a\u041e\u0441\u043d\u043e\u0432\u043d\u044b\u043c\u0438 \u0434\u0440\u0430\u0439\u0432\u0435\u0440\u0430\u043c\u0438 \u0443\u0432\u0435\u043b\u0438\u0447\u0435\u043d\u0438\u044f \u000d\u000a\u043f\u043e\u0442\u0440\u0435\u0431\u043b\u0435\u043d\u0438\u044f \u043c\u0435\u0434\u0438 \u0441\u0442\u0430\u043d\u0443\u0442 \u0440\u0430\u0441\u043f\u0440\u043e\u0441\u0442\u0440\u0430\u043d\u0435\u043d\u0438\u0435 \u000d\u000a\u044d\u043b\u0435\u043a\u0442\u0440\u043e\u043c\u043e\u0431\u0438\u043b\u0435\u0439, \u0437\u0435\u043b\u0435\u043d\u0430\u044f \u044d\u043d\u0435\u0440\u0433\u0435\u0442\u0438\u043a\u0430, \u0430 \u0442\u0430\u043a\u0436\u0435 \u000d\u000a\u044d\u043b\u0435\u043a\u0442\u0440\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044f \u0437\u0434\u0430\u043d\u0438\u0439 \u0438 \u0441\u0442\u0440\u043e\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u000d\u000a\u044d\u043b\u0435\u043a\u0442\u0440\u043e\u0441\u0435\u0442\u0435\u0439.\u000a\u000d\u000a\u041f\u043e \u043f\u0440\u043e\u0433\u043d\u043e\u0437\u0430\u043c S&P Global, \u044d\u043d\u0435\u0440\u0433\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u000d\u000a\u043f\u0435\u0440\u0435\u0445\u043e\u0434 \u0441\u0442\u0430\u043d\u0435\u0442 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u043c \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u043e\u043c \u0440\u043e\u0441\u0442\u0430 \u000d\u000a\u0441\u043f\u0440\u043e\u0441\u0430 \u043d\u0430 \u043c\u0435\u0434\u044c \u0441 2025 \u043f\u043e 2040 \u0433\u043e\u0434: \u0432 \u043e\u0431\u0449\u0435\u0439 \u000d\u000a\u0441\u043b\u043e\u0436\u043d\u043e\u0441\u0442\u0438 \u043d\u0430 \u043d\u0435\u0433\u043e \u043f\u0440\u0438\u0434\u0435\u0442\u0441\u044f 7,1 \u043c\u043b\u043d \u000d\u000a\u0433\u043e\u0432\u043e\u0440\u0438\u0442\u0441\u044f\u000d\u000a\u043c\u0435\u0442\u0440\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u0442\u043e\u043d\u043d \u0433\u043e\u0434\u043e\u0432\u043e\u0433\u043e \u0441\u043f\u0440\u043e\u0441\u0430 \u043d\u0430 \u044d\u0442\u043e\u0442 \u000d\u000a\u043c\u0435\u0442\u0430\u043b\u043b \u0441 \u043d\u0430\u0441\u0442\u043e\u044f\u0449\u0435\u0433\u043e \u0432\u0440\u0435\u043c\u0435\u043d\u0438 \u0434\u043e 2040 \u0433\u043e\u0434\u0430. \u000d\u000a\u0414\u043e\u043b\u044f \u044d\u043d\u0435\u0440\u0433\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u043f\u0435\u0440\u0435\u0445\u043e\u0434\u0430 \u0432 \u043c\u0438\u0440\u043e\u0432\u043e\u043c \u000d\u000a\u043f\u043e\u0442\u0440\u0435\u0431\u043b\u0435\u043d\u0438\u0438 \u0443\u0432\u0435\u043b\u0438\u0447\u0438\u0442\u0441\u044f \u0441 8,5 \u043c\u043b\u043d \u043c\u0435\u0442\u0440\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u000d\u000a\u0442\u043e\u043d\u043d \u0432 2025 \u0433\u043e\u0434\u0443 \u0434\u043e 15,6 \u043c\u043b\u043d \u043c\u0435\u0442\u0440\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u0442\u043e\u043d\u043d \u000d\u000a\u0432 2040 \u0433\u043e\u0434\u0443, \u0447\u0442\u043e \u0441\u043e\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u0435\u0442 \u0433\u043e\u0434\u043e\u0432\u043e\u043c\u0443 \u0440\u043e\u0441\u0442\u0443 \u000d\u000a\u043d\u0430 4,1%. \u000a\u000d\u000a\u041b\u0438\u0434\u0435\u0440\u0430\u043c\u0438 \u0441 \u0442\u043e\u0447\u043a\u0438 \u0437\u0440\u0435\u043d\u0438\u044f \u0443\u0432\u0435\u043b\u0438\u0447\u0435\u043d\u0438\u044f \u0441\u043f\u0440\u043e\u0441\u0430 \u000d\u000a\u043d\u0430 \u043c\u0435\u0434\u044c \u0432 \u0441\u0432\u044f\u0437\u0438 \u0441 \u044d\u043d\u0435\u0440\u0433\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u043c \u043f\u0435\u0440\u0435\u0445\u043e\u0434\u043e\u043c \u000d\u000a\u0441 2025 \u043f\u043e 2040 \u0433\u043e\u0434 \u0441\u0442\u0430\u043d\u0443\u0442 \u041a\u0438\u0442\u0430\u0439 (\u0440\u043e\u0441\u0442 \u2028\u000d\u000a\u043d\u0430 1,9 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u043c\u0435\u0434\u0438), \u0441\u0442\u0440\u0430\u043d\u044b \u0410\u0437\u0438\u0430\u0442\u0441\u043a\u043e\u0422\u0438\u0445\u043e\u043e\u043a\u0435\u0430\u043d\u0441\u043a\u043e\u0433\u043e \u0440\u0435\u0433\u0438\u043e\u043d\u0430 (1,6 \u043c\u043b\u043d \u0442\u043e\u043d\u043d) \u2028\u000d\u000a\u0438 \u0415\u0432\u0440\u043e\u043f\u0430 (1,4 \u043c\u043b\u043d \u0442\u043e\u043d\u043d).\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u0414\u0420\u041a \u043f\u0435\u0440\u0435\u0434\u0430\u0441\u0442 \u0421\u0428\u0410 \u0441\u043f\u0438\u0441\u043e\u043a \u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u0439 \u000d\u000a\u0434\u043b\u044f \u0441\u043d\u0438\u0436\u0435\u043d\u0438\u044f \u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u0438 \u043e\u0442 \u041a\u0438\u0442\u0430\u044f\u000d\u000a\u041e\u043d \u0431\u0443\u0434\u0435\u0442 \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d \u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u043e\u0439 \u0441\u0442\u043e\u0440\u043e\u043d\u0435 \u043d\u0430 \u044d\u0442\u043e\u0439 \u043d\u0435\u0434\u0435\u043b\u0435.\u000d\u000a\u041f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u0414\u0435\u043c\u043e\u043a\u0440\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u0420\u0435\u0441\u043f\u0443\u0431\u043b\u0438\u043a\u0438 \u000d\u000a\u041a\u043e\u043d\u0433\u043e (\u0414\u0420\u041a) \u0432 \u043d\u0430\u0441\u0442\u043e\u044f\u0449\u0435\u0435 \u0432\u0440\u0435\u043c\u044f \u000d\u000a\u0434\u043b\u044f \u0421\u0428\u0410 \u0441\u043f\u0438\u0441\u043e\u043a \u0441\u0442\u0440\u0430\u0442\u0435\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u000d\u000a\u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u0439 \u0434\u043b\u044f \u043f\u0440\u0438\u0432\u043b\u0435\u0447\u0435\u043d\u0438\u044f \u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u0438\u0445 \u000d\u000a\u0438\u043d\u0432\u0435\u0441\u0442\u043e\u0440\u043e\u0432 \u0438 \u0441\u043d\u0438\u0436\u0435\u043d\u0438\u044f \u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u0438 \u043e\u0442 \u041a\u0438\u0442\u0430\u044f \u000d\u000a\u0432 \u0433\u043e\u0440\u043d\u043e\u0434\u043e\u0431\u044b\u0432\u0430\u044e\u0449\u0435\u0439 \u043e\u0442\u0440\u0430\u0441\u043b\u0438.\u000a\u000d\u000a\u041a\u0430\u043a \u0437\u0430\u044f\u0432\u0438\u043b \u043c\u0438\u043d\u0438\u0441\u0442\u0440 \u043f\u043e \u0434\u0435\u043b\u0430\u043c \u0448\u0430\u0445\u0442 \u041b\u0443\u0438 \u0412\u0430\u0442\u0443\u043c \u000d\u000a\u041a\u0430\u0431\u0430\u043c\u0431\u0430, \u043f\u0435\u0440\u0435\u0447\u0435\u043d\u044c \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u044b\u0445 \u043f\u0440\u043e\u0435\u043a\u0442\u043e\u0432 \u0431\u0443\u0434\u0435\u0442 \u000d\u000a\u043f\u0435\u0440\u0435\u0434\u0430\u043d \u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u043e\u0439 \u0441\u0442\u043e\u0440\u043e\u043d\u0435 \u0443\u0436\u0435 \u043d\u0430 \u044d\u0442\u043e\u0439 \u000d\u000a\u043d\u0435\u0434\u0435\u043b\u0435. \u041f\u043e \u0441\u043b\u043e\u0432\u0430\u043c \u043c\u0438\u043d\u0438\u0441\u0442\u0440\u0430, \u0440\u0435\u0447\u0438 \u043e \u043a\u0430\u043a\u0438\u0445-\u043b\u0438\u0431\u043e \u000d\u000a\u043f\u0440\u0435\u0444\u0435\u0440\u0435\u043d\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u0445 \u0443\u0441\u043b\u043e\u0432\u0438\u044f\u0445 \u0434\u043b\u044f \u0421\u0428\u0410 \u000d\u000a\u043f\u0440\u043e\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u0435\u0442\u000d\u000a\u043d\u0435 \u0438\u0434\u0435\u0442 \u043f\u0435\u0440\u0435\u0433\u043e\u0432\u043e\u0440\u044b \u0431\u0443\u0434\u0443\u0442 \u0432\u0435\u0441\u0442\u0438\u0441\u044c \u000d\u000a\u043d\u0430 \u043a\u043e\u043c\u043c\u0435\u0440\u0447\u0435\u0441\u043a\u043e\u0439 \u043e\u0441\u043d\u043e\u0432\u0435.\u000a\u000d\u000a\u0412\u043b\u0430\u0441\u0442\u0438 \u0414\u0420\u041a \u043f\u043b\u0430\u043d\u0438\u0440\u0443\u044e\u0442 \u043e\u0441\u043b\u0430\u0431\u0438\u0442\u044c \u000d\u000a\u0434\u043e\u043c\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0439 \u0438\u0437 \u041a\u041d\u0420 \u0432 \u0433\u043e\u0440\u043d\u043e\u0439 \u000d\u000a\u043f\u0440\u043e\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u043e\u0441\u0442\u0438. \u0412 2007 \u0433\u043e\u0434\u0443 \u0430\u0444\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u0430\u044f \u000d\u000a\u0441\u0442\u0440\u0430\u043d\u0430 \u043f\u0440\u0435\u0434\u043e\u0441\u0442\u0430\u0432\u0438\u043b\u0430 \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u043c \u000d\u000a\u0433\u043e\u0440\u043d\u043e\u0434\u043e\u0431\u044b\u0432\u0430\u044e\u0449\u0438\u043c \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u044f\u043c \u043d\u0430\u043b\u043e\u0433\u043e\u0432\u044b\u0435 \u000d\u000a\u043b\u044c\u0433\u043e\u0442\u044b \u0434\u043e 2040 \u0433\u043e\u0434\u0430. \u0412\u0437\u0430\u043c\u0435\u043d \u041a\u0438\u0442\u0430\u0439 \u0434\u043e\u043b\u0436\u0435\u043d \u0431\u044b\u043b \u000d\u000a\u043e\u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0438\u0442\u044c \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0438 \u0432 \u0440\u0430\u0437\u043c\u0435\u0440\u0435 $9 \u043c\u043b\u0440\u0434, \u000d\u000a\u043e\u0434\u043d\u0430\u043a\u043e \u043a \u043d\u0430\u0441\u0442\u043e\u044f\u0449\u0435\u043c\u0443 \u043c\u043e\u043c\u0435\u043d\u0442\u0443 \u043e\u0431\u044a\u0435\u043c \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u0445 \u000d\u000a\u043a\u0430\u043f\u0438\u0442\u0430\u043b\u043e\u0432\u043b\u043e\u0436\u0435\u043d\u0438\u0439 \u0434\u043e\u0441\u0442\u0438\u0433 \u043b\u0438\u0448\u044c $6 \u043c\u043b\u0440\u0434.\u000d\u000a07 09","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a \u0438 \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 12\u201316 \u044f\u043d\u0432\u0430\u0440\u044f 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u0410\u0434\u043c\u0438\u043d\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u044f \u0422\u0440\u0430\u043c\u043f\u0430 \u043d\u0430\u043c\u0435\u0440\u0435\u043d\u0430 \u043f\u043e\u0434\u043e\u0440\u0432\u0430\u0442\u044c \u000d\u000a\u0434\u043e\u043c\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435 \u041a\u0438\u0442\u0430\u044f \u0432 \u0440\u0435\u0434\u043a\u043e\u0437\u0435\u043c\u0435\u043b\u044c\u043d\u044b\u0445 \u043c\u0435\u0442\u0430\u043b\u043b\u0430\u0445\u000d\u000a\u0412 \u0421\u0428\u0410 \u0441\u0447\u0438\u0442\u0430\u044e\u0442, \u0447\u0442\u043e \u041a\u041d\u0420 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442 \u0438\u0445 \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0438 \u043a\u0430\u043a \u0440\u044b\u0447\u0430\u0433 \u0432 \u0442\u043e\u0440\u0433\u043e\u0432\u044b\u0445 \u0432\u043e\u0439\u043d\u0430\u0445.\u000d\u000a\u0421\u0442\u0430\u0440\u0448\u0438\u0439 \u0441\u043e\u0432\u0435\u0442\u043d\u0438\u043a \u043f\u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442\u0430 \u0421\u0428\u0410 \u0414\u043e\u043d\u0430\u043b\u044c\u0434\u0430 \u000d\u000a\u0422\u0440\u0430\u043c\u043f\u0430 \u043f\u043e \u0442\u043e\u0440\u0433\u043e\u0432\u043b\u0435 \u0438 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0443 \u041f\u0438\u0442\u0435\u0440 \u000d\u000a\u041d\u0430\u0432\u0430\u0440\u0440\u043e , \u0447\u0442\u043e \u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u0430\u044f \u000d\u000a\u0430\u0434\u043c\u0438\u043d\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u044f \u043d\u0430\u043c\u0435\u0440\u0435\u043d\u0430 \u043f\u043e\u0434\u043e\u0440\u0432\u0430\u0442\u044c \u000d\u000a\u0434\u043e\u043c\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435 \u041a\u0438\u0442\u0430\u044f \u0432 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0435 \u000d\u000a\u043a\u0440\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u0432\u0430\u0436\u043d\u044b\u0445 \u043c\u0438\u043d\u0435\u0440\u0430\u043b\u043e\u0432 \u000d\u000a\u0438 \u0440\u0435\u0434\u043a\u043e\u0437\u0435\u043c\u0435\u043b\u044c\u043d\u044b\u0445 \u043c\u0435\u0442\u0430\u043b\u043b\u043e\u0432.\u000d\u000a\u0437\u0430\u044f\u0432\u0438\u043b\u000d\u000a\u0412 \u043d\u0430\u0441\u0442\u043e\u044f\u0449\u0435\u0435 \u0432\u0440\u0435\u043c\u044f \u041f\u0435\u043a\u0438\u043d \u0440\u0435\u0433\u0443\u043b\u044f\u0440\u043d\u043e \u0443\u0433\u0440\u043e\u0436\u0430\u0435\u0442 \u000d\u000a\u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0438\u0442\u044c \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0438 \u0440\u0435\u0434\u043a\u043e\u0437\u0435\u043c\u0435\u043b\u044c\u043d\u044b\u0445 \u043c\u0435\u0442\u0430\u043b\u043b\u043e\u0432 \u000d\u000a\u0434\u043b\u044f \u0434\u0430\u0432\u043b\u0435\u043d\u0438\u044f \u043d\u0430 \u0441\u0432\u043e\u0438\u0445 \u0442\u043e\u0440\u0433\u043e\u0432\u044b\u0445 \u043f\u0430\u0440\u0442\u043d\u0435\u0440\u043e\u0432, \u0432 \u0442\u043e\u043c \u000d\u000a\u0447\u0438\u0441\u043b\u0435 \u0421\u0428\u0410 \u0438 \u0415\u0432\u0440\u043e\u0441\u043e\u044e\u0437. \u041a\u0438\u0442\u0430\u0439, \u0441\u043e \u0441\u0432\u043e\u0435\u0439 \u0441\u0442\u043e\u0440\u043e\u043d\u044b, \u000d\u000a\u00ab\u0438\u0433\u0440\u0430\u0435\u0442 \u043c\u0443\u0441\u043a\u0443\u043b\u0430\u043c\u0438\u00bb \u0432 \u0442\u043e\u0440\u0433\u043e\u0432\u044b\u0445 \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u0430\u0445, \u0442\u0430\u043a \u000d\u000a\u043a\u0430\u043a \u0441\u0447\u0438\u0442\u0430\u0435\u0442, \u0447\u0442\u043e \u043e\u0431\u043b\u0430\u0434\u0430\u0435\u0442 \u043c\u043e\u043d\u043e\u043f\u043e\u043b\u0438\u0435\u0439 \u000d\u000a\u043d\u0430 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u043d\u044b\u0445 \u044d\u043b\u0435\u043c\u0435\u043d\u0442\u043e\u0432.\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u0421\u043f\u0440\u043e\u0441 \u043d\u0430 \u043c\u0435\u0434\u044c \u0434\u043b\u044f \u0441\u0442\u0440\u043e\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0430 \u0434\u0430\u0442\u0430-\u0446\u0435\u043d\u0442\u0440\u043e\u0432 \u000d\u000a\u0432\u044b\u0440\u0430\u0441\u0442\u0435\u0442 \u043a 2040-\u043c\u0443 \u0434\u043e 2,5 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u0432 \u0433\u043e\u0434\u000d\u000a\u0412\u044b\u0447\u0438\u0441\u043b\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0438 \u043e\u0442\u0440\u0430\u0441\u043b\u0438 \u043a \u044d\u0442\u043e\u043c\u0443 \u0441\u0440\u043e\u043a\u0443 \u0443\u0432\u0435\u043b\u0438\u0447\u0430\u0442\u0441\u044f \u0432 \u043f\u044f\u0442\u044c \u0440\u0430\u0437.\u000d\u000a\u0420\u0430\u0441\u043f\u0440\u043e\u0441\u0442\u0440\u0430\u043d\u0435\u043d\u0438\u0435 \u0442\u0435\u0445\u043d\u043e\u043b\u043e\u0433\u0438\u0439 \u0438\u0441\u043a\u0443\u0441\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0433\u043e \u000d\u000a\u0438\u043d\u0442\u0435\u043b\u043b\u0435\u043a\u0442\u0430 \u043a 2040 \u0433\u043e\u0434\u0443 \u043f\u0440\u0438\u0432\u0435\u0434\u0435\u0442 \u043a \u0440\u043e\u0441\u0442\u0443 \u000d\u000a\u0441\u043f\u0440\u043e\u0441\u0430 \u043d\u0430 \u043c\u0435\u0434\u044c \u0441\u043e \u0441\u0442\u043e\u0440\u043e\u043d\u044b \u043f\u0440\u043e\u0435\u043a\u0442\u043e\u0432 \u000d\u000a\u043f\u043e \u0441\u0442\u0440\u043e\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0443 \u0446\u0435\u043d\u0442\u0440\u043e\u0432 \u043e\u0431\u0440\u0430\u0431\u043e\u0442\u043a\u0438 \u0434\u0430\u043d\u043d\u044b\u0445 \u000d\u000a\u0441 \u043d\u044b\u043d\u0435\u0448\u043d\u0438\u0445 1,1 \u043c\u043b\u043d \u0434\u043e 2,5 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u0432 \u0433\u043e\u0434, \u000d\u000a S&P Global.\u000a\u000d\u000a\u0412 \u043f\u0440\u043e\u0433\u043d\u043e\u0437\u0435 \u043f\u043e\u0434\u0447\u0435\u0440\u043a\u0438\u0432\u0430\u0435\u0442\u0441\u044f, \u0447\u0442\u043e \u0430\u043a\u0442\u0438\u0432\u043d\u043e\u0435 \u000d\u000a\u0432\u043d\u0435\u0434\u0440\u0435\u043d\u0438\u0435 \u0442\u0435\u0445\u043d\u043e\u043b\u043e\u0433\u0438\u0439 \u0433\u0435\u043d\u0435\u0440\u0430\u0442\u0438\u0432\u043d\u043e\u0433\u043e \u000d\u000a\u0438\u0441\u043a\u0443\u0441\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0433\u043e \u0438\u043d\u0442\u0435\u043b\u043b\u0435\u043a\u0442\u0430 (GenAI) \u0443\u0436\u0435 \u000d\u000a\u043f\u0440\u0438\u0432\u0435\u043b\u043e \u043a \u0442\u0440\u0430\u043d\u0441\u0444\u043e\u0440\u043c\u0430\u0446\u0438\u044f\u043c \u0432 \u0438\u043d\u0434\u0443\u0441\u0442\u0440\u0438\u0438 \u0434\u0430\u0442\u0430\u000d\u000a\u0446\u0435\u043d\u0442\u0440\u043e\u0432. \u0421\u0443\u043c\u043c\u0430\u0440\u043d\u0430\u044f \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u043d\u0430\u044f \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u044c \u000d\u000a\u0432\u0441\u0435\u0445 \u0446\u0435\u043d\u0442\u0440\u043e\u0432 \u043e\u0431\u0440\u0430\u0431\u043e\u0442\u043a\u0438 \u0434\u0430\u043d\u043d\u044b\u0445 \u0432\u044b\u0440\u0430\u0441\u0442\u0435\u0442 \u000d\u000a\u0441\u043e 100 \u0413\u0412\u0442 \u0432 2022 \u0433\u043e\u0434\u0443 (\u0442\u043e\u0433\u0434\u0430 \u0441\u043e\u0441\u0442\u043e\u044f\u043b\u0441\u044f \u0440\u0435\u043b\u0438\u0437 \u000d\u000aChatGPT) \u0434\u043e \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e 550 \u0413\u0412\u0442 \u043a 2040 \u0433\u043e\u0434\u0443.\u000a\u000d\u000a\u0410\u0432\u0442\u043e\u0440\u044b \u0434\u043e\u043a\u043b\u0430\u0434\u0430 \u043e\u0436\u0438\u0434\u0430\u044e\u0442, \u0447\u0442\u043e \u043f\u043e \u043c\u0435\u043d\u044c\u0448\u0435\u0439 \u043c\u0435\u0440\u0435 \u000d\u000a\u0434\u043e 2030 \u0433\u043e\u0434\u0430 \u0431\u0443\u0434\u0443\u0442 \u0435\u0436\u0435\u0433\u043e\u0434\u043d\u043e \u0432\u0432\u043e\u0434\u0438\u0442\u044c\u0441\u044f \u000d\u000a\u043f\u0440\u043e\u0433\u043d\u043e\u0437\u0438\u0440\u0443\u0435\u0442\u000d\u000a\u0432 \u044d\u043a\u0441\u043f\u043b\u0443\u0430\u0442\u0430\u0446\u0438\u044e \u0434\u0430\u0442\u0430 \u0446\u0435\u043d\u0442\u0440\u044b \u0441 \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u043d\u043e\u0439 \u000d\u000a\u043c\u043e\u0449\u043d\u043e\u0441\u0442\u044c\u044e \u043e\u043a\u043e\u043b\u043e 30 \u0413\u0412\u0442. \u041f\u0440\u0438 \u044d\u0442\u043e\u043c 58% \u000d\u000a\u043f\u043e\u0442\u0440\u0435\u0431\u043b\u0435\u043d\u0438\u044f \u043c\u0435\u0434\u0438 \u0431\u0443\u0434\u0435\u0442 \u043f\u0440\u0438\u0445\u043e\u0434\u0438\u0442\u044c\u0441\u044f \u000d\u000a\u043d\u0430 \u0446\u0435\u043d\u0442\u0440\u044b \u043e\u0431\u0440\u0430\u0431\u043e\u0442\u043a\u0438 \u0434\u0430\u043d\u043d\u044b\u0445 \u0434\u043b\u044f \u0442\u0430\u043a \u000d\u000a\u043d\u0430\u0437\u044b\u0432\u0430\u0435\u043c\u043e\u0433\u043e \u043e\u0431\u0443\u0447\u0435\u043d\u0438\u044f \u0418\u0418. \u0412 \u0442\u043e \u0432\u0440\u0435\u043c\u044f \u043a\u0430\u043a \u000d\u000a\u043f\u043e\u0441\u043b\u0435 2035 \u0433\u043e\u0434\u0430 \u0438\u0445 \u0440\u043e\u0441\u0442 \u0441\u0442\u0430\u0431\u0438\u043b\u0438\u0437\u0438\u0440\u0443\u0435\u0442\u0441\u044f, \u000d\u000a\u0430 \u043d\u043e\u0432\u044b\u043c \u0434\u0440\u0430\u0439\u0432\u0435\u0440\u043e\u043c \u043e\u0442\u0440\u0430\u0441\u043b\u0438 \u0441\u0442\u0430\u043d\u0443\u0442 \u000d\u000a\u0432\u044b\u0447\u0438\u0441\u043b\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0438 \u0434\u043b\u044f \u0440\u043e\u0431\u043e\u0442\u043e\u0442\u0435\u0445\u043d\u0438\u043a\u0438 \u000d\u000a\u0438 \u0431\u0435\u0441\u043f\u0438\u043b\u043e\u0442\u043d\u044b\u0445 \u0430\u0432\u0442\u043e\u043c\u043e\u0431\u0438\u043b\u0435\u0439.\u000a\u000d\u000a\u041f\u0440\u0438 \u044d\u0442\u043e\u043c \u043d\u0430 \u041a\u0438\u0442\u0430\u0439 \u043f\u0440\u0438\u0445\u043e\u0434\u0438\u0442\u0441\u044f \u043e\u043a\u043e\u043b\u043e \u2028\u000d\u000a12 \u0438\u0437 29 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u043c\u0438\u0440\u043e\u0432\u043e\u0439 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0438 \u000d\u000a\u043f\u043e \u0432\u044b\u043f\u043b\u0430\u0432\u043a\u0435 \u043c\u0435\u0434\u0438. S&P Global \u043e\u0442\u043c\u0435\u0447\u0430\u0435\u0442, \u0447\u0442\u043e \u044d\u0442\u0430 \u000d\u000a\u0446\u0438\u0444\u0440\u0430 \u0440\u0430\u0441\u0442\u0435\u0442, \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u043e\u0436\u0438\u0434\u0430\u0435\u0442\u0441\u044f \u0434\u0430\u043b\u044c\u043d\u0435\u0439\u0448\u0430\u044f \u000d\u000a\u043a\u043e\u043d\u0446\u0435\u043d\u0442\u0440\u0430\u0446\u0438\u044f \u043f\u0435\u0440\u0435\u0440\u0430\u0431\u043e\u0442\u043a\u0438 \u043d\u0430 \u0433\u043b\u043e\u0431\u0430\u043b\u044c\u043d\u043e\u043c \u000d\u000a\u0440\u044b\u043d\u043a\u0435.\u000d\u000a08 09","\u041a\u0438\u0442\u0430\u0439 12\u201316 \u044f\u043d\u0432\u0430\u0440\u044f 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u0412\u043b\u0430\u0441\u0442\u0438 \u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0438 \u0443\u0447\u0442\u0443\u0442 \u0438\u043d\u0442\u0435\u0440\u0435\u0441\u044b \u043c\u0435\u0442\u0430\u043b\u043b\u0443\u0440\u0433\u043e\u0432 \u2028\u000d\u000a\u043f\u0440\u0438 \u0441\u043e\u043a\u0440\u0430\u0449\u0435\u043d\u0438\u0438 \u043a\u0432\u043e\u0442 \u043d\u0430 \u0434\u043e\u0431\u044b\u0447\u0443 \u043d\u0438\u043a\u0435\u043b\u0435\u0432\u043e\u0439 \u0440\u0443\u0434\u044b\u000d\u000a\u041f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u043e\u0431\u0435\u0449\u0430\u0435\u0442 \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0438\u0442\u044c \u0440\u0430\u0432\u043d\u044b\u0439 \u0434\u043e\u0441\u0442\u0443\u043f \u043a \u0440\u0443\u0434\u0435 \u0441\u043e \u0441\u0442\u043e\u0440\u043e\u043d\u044b \u043f\u0435\u0440\u0435\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u044e\u0449\u0438\u0445 \u2028\u000d\u000a\u0435\u0435 \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u0439.\u000d\u000a\u041f\u0440\u0438 \u0441\u043e\u043a\u0440\u0430\u0449\u0435\u043d\u0438\u0438 \u043a\u0432\u043e\u0442 \u043d\u0430 \u0434\u043e\u0431\u044b\u0447\u0443 \u043d\u0438\u043a\u0435\u043b\u0435\u0432\u043e\u0439 \u000d\u000a\u0440\u0443\u0434\u044b \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u0443\u0447\u0442\u0435\u0442 \u0438\u043d\u0442\u0435\u0440\u0435\u0441\u044b \u000d\u000a\u043c\u0435\u0442\u0430\u043b\u043b\u0443\u0440\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432, \u000d\u000a\u043c\u0438\u043d\u0438\u0441\u0442\u0440 \u044d\u043d\u0435\u0440\u0433\u0435\u0442\u0438\u043a\u0438 \u0438 \u043c\u0438\u043d\u0435\u0440\u0430\u043b\u044c\u043d\u044b\u0445 \u0440\u0435\u0441\u0443\u0440\u0441\u043e\u0432 \u000d\u000a\u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0438 \u0411\u0430\u0445\u043b\u0438\u043b \u041b\u0430\u0445\u0430\u0434\u0430\u043b\u0438\u0430. \u000a\u000d\u000a\u041b\u0430\u0445\u0430\u0434\u0430\u043b\u0438\u0430 \u043f\u043e\u0434\u0447\u0435\u0440\u043a\u043d\u0443\u043b, \u0447\u0442\u043e \u0435\u0433\u043e \u0432\u0435\u0434\u043e\u043c\u0441\u0442\u0432\u043e \u000d\u000a\u043d\u0435 \u0434\u043e\u043f\u0443\u0441\u0442\u0438\u0442 \u0444\u043e\u0440\u043c\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f \u043d\u0430 \u0440\u044b\u043d\u043a\u0435 \u000d\u000a\u043c\u043e\u043d\u043e\u043f\u043e\u043b\u0438\u0439 \u043a\u0440\u0443\u043f\u043d\u044b\u0445 \u0438\u0433\u0440\u043e\u043a\u043e\u0432. \u0412\u043b\u0430\u0441\u0442\u0438 \u043d\u0435 \u0445\u043e\u0442\u044f\u0442 \u000d\u000a\u0434\u043e\u043f\u0443\u0441\u0442\u0438\u0442\u044c \u043f\u0440\u043e\u0441\u0442\u043e\u044f \u043a\u043e\u043c\u0431\u0438\u043d\u0430\u0442\u043e\u0432 \u0438\u0437-\u0437\u0430 \u043d\u0435\u0445\u0432\u0430\u0442\u043a\u0438 \u000d\u000a\u0440\u0443\u0434\u044b \u0438 \u043f\u043b\u0430\u043d\u0438\u0440\u0443\u044e\u0442 \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0438\u0442\u044c \u043a \u043d\u0435\u0439 \u0440\u0430\u0432\u043d\u044b\u0439 \u0434\u043b\u044f \u000d\u000a\u0432\u0441\u0435\u0445 \u0434\u043e\u0441\u0442\u0443\u043f.\u000d\u000a\u043f\u043e\u043e\u0431\u0435\u0449\u0430\u043b\u000d\u000a\u0412 \u043a\u043e\u043d\u0446\u0435 \u0434\u0435\u043a\u0430\u0431\u0440\u044f \u043c\u0438\u043d\u0438\u0441\u0442\u0440 \u0441\u043e\u043e\u0431\u0449\u0438\u043b, \u0447\u0442\u043e \u000d\u000a\u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u044f \u043d\u0430\u043c\u0435\u0440\u0435\u043d\u0430 \u0441\u043e\u043a\u0440\u0430\u0442\u0438\u0442\u044c \u043e\u0431\u044a\u0435\u043c\u044b \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u043d\u0438\u043a\u0435\u043b\u044f. \u042d\u0442\u043e \u0440\u0435\u0448\u0435\u043d\u0438\u0435 \u043f\u0440\u0438\u043d\u044f\u0442\u043e \u000d\u000a\u0434\u043b\u044f \u0441\u0442\u0430\u0431\u0438\u043b\u0438\u0437\u0430\u0446\u0438\u0438 \u0446\u0435\u043d \u043d\u0430 \u043c\u0435\u0442\u0430\u043b\u043b. \u041f\u043e \u0434\u0430\u043d\u043d\u044b\u043c \u000d\u000a\u0410\u0441\u0441\u043e\u0446\u0438\u0430\u0446\u0438\u0438 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u0435\u0439 \u043d\u0438\u043a\u0435\u043b\u044f \u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0438 \u000d\u000a(APNI), \u0440\u0435\u0447\u044c \u043c\u043e\u0436\u0435\u0442 \u0438\u0434\u0442\u0438 \u043e \u0441\u043e\u043a\u0440\u0430\u0449\u0435\u043d\u0438\u0438 \u043e\u0431\u0449\u0435\u0433\u043e \u000d\u000a\u043e\u0431\u044a\u0435\u043c\u0430 \u043a\u0432\u043e\u0442 \u043d\u0430 \u043d\u0438\u043a\u0435\u043b\u0435\u0432\u0443\u044e \u0440\u0443\u0434\u0443 \u0441 379 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u000d\u000a\u0432 2025 \u0433\u043e\u0434\u0443 \u0434\u043e 250 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u0432 2026 \u0433\u043e\u0434\u0443.\u000d\u000a09 09"]